import click
from click.testing import CliRunner

def make(order):
    def deco(f):
        if order == "a":
            f = click.option("--without-xyz", "xyz", flag_value=False)(f)
            f = click.option("--with-xyz", "xyz", flag_value=True, default=True)(f)
        else:
            f = click.option("--with-xyz", "xyz", flag_value=True, default=True)(f)
            f = click.option("--without-xyz", "xyz", flag_value=False)(f)
        return f
    @click.command()
    @deco
    def cli(xyz):
        click.echo(repr(xyz))
    return cli

r = CliRunner()
for order in ("a", "b"):
    for args in ([], ["--with-xyz"], ["--without-xyz"], ["--with-xyz","--without-xyz"], ["--without-xyz","--with-xyz"]):
        res = r.invoke(make(order), args, standalone_mode=False, catch_exceptions=False)
        print(order, args, "->", res.return_value if res.return_value is not None else res.output.strip())
